// Smart RAG Check: decide si consultar la base de conocimiento en este turno.
// (version inline del patron; ver examples/smart-rag-check.js para el detalle)
const stage = $json.lead_stage || 'new';
const tenant = $json;
const earlyStages = ['new', 'discovery', 'qualifying'];
const useRag = tenant.rag_enabled !== false && earlyStages.includes(stage);
return [{ json: { ...$json, use_rag: useRag, top_k: tenant.rag_top_k || 4 } }];

// Sanitizacion determinista POST-LLM (version inline).
// Ver examples/sanitize-output.js para el patron completo (parse, leak detect, fallback).
const raw = $json.body || $json.output || '';
let reply = String(raw).replace(/^\s*(assistant|bot)\s*:\s*/i, '').trim();
const leak = /system\s*prompt|api[_-]?key|bearer/i.test(reply);
if (leak || reply.length === 0) {
  return [{ json: { text: 'Disculpa, no pude procesar eso. Podes reformularlo?', leak, persist: false } }];
}
return [{ json: { text: reply.slice(0, 1500), leak: false, persist: true } }];
